export function showsCustomer(state) {
  return state.mode !== "pickup" && state.stage !== "pickup" && state.stage !== "hub" && state.customer != null;
}

export function createState(scenarioId = "pickup") {
  const source = SCENARIOS[scenarioId] || SCENARIOS.pickup;
  const pickupOnly = source.mode === "pickup";
  return {
    scenario: scenarioId,
    mode: source.mode,
    screen: "UI-07",
    theme: "light",
    offline: Boolean(source.offline),
    device: "new",
    location: source.location || "unknown",
    camera: "unknown",
    shift: source.shift || "off",
    stage: source.shift === "active" ? "delivery" : "idle",
    offer: "none",
    parcels: source.parcels.map((item) => ({ ...item })),
    merchant: source.merchant,
    area: source.area,
    customer: pickupOnly ? null : (source.mode === "hybrid" ? null : source.customer),
    sealedCustomer: source.mode === "hybrid" ? source.customer : null,
    codExpected: pickupOnly ? null : (source.mode === "hybrid" ? null : source.cod),
    sealedCod: source.mode === "hybrid" ? source.cod : null,
    codActual: null,
    held: source.held || 0,
    pendingRemit: 0,
    earnings: source.earnings || 0,
    receipt: null,
    sync: (source.sync || []).map((item) => ({ ...item })),
    pickup: "open",
    hub: "open",
    delivery: "open",
    returnTask: source.returnTask ? { ...source.returnTask } : null,
    awaiting: null,
    history: [],
    dialog: null,
    error: "",
    draftPhone: "",
    nav: "home",
    clock: "09:41",
    position: null,
    scanNote: "",
  };
}
